import { test, expect } from '@playwright/test';

test.describe('Checkout Form Mobile Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should stack checkout form fields vertically on mobile screen', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 862 });

    // Verify form fields are visible
    const emailField = page.getByLabel('Email Address');
    const cardNumberField = page.getByLabel('Card Number');
    const expiryField = page.getByLabel('Expiry Date');
    const cvvField = page.getByLabel('CVV');
    const billingAddressField = page.getByLabel('Billing Address');
    const submitButton = page.getByRole('button', { name: 'Place Order' });

    await expect(emailField).toBeVisible();
    await expect(cardNumberField).toBeVisible();
    await expect(expiryField).toBeVisible();
    await expect(cvvField).toBeVisible();
    await expect(billingAddressField).toBeVisible();
    await expect(submitButton).toBeVisible();

    // Fill in form fields
    await emailField.fill('user@example.com');
    await cardNumberField.fill('4111111111111111');
    await expiryField.fill('12/25');
    await cvvField.fill('123');
    await billingAddressField.fill('123 Main St');

    // Verify form fields are stacked vertically (check display style)
    const formContainer = page.locator('[data-testid="checkout-form-container"]');
    const fieldElements = page.locator('[data-testid="form-field"]');
    const fieldCount = await fieldElements.count();

    // Verify all fields are present
    expect(fieldCount).toBe(5);

    // Verify fields are stacked (check display style)
    const firstField = fieldElements.first();
    const secondField = fieldElements.nth(1);

    const firstDisplay = await firstField.evaluate((el) => window.getComputedStyle(el).display);
    const secondDisplay = await secondField.evaluate((el) => window.getComputedStyle(el).display);

    expect(firstDisplay).toBe('block');
    expect(secondDisplay).toBe('block');

    // Verify submit button is also block level
    const buttonDisplay = await submitButton.evaluate((el) => window.getComputedStyle(el).display);
    expect(buttonDisplay).toBe('block');

    // Submit the form
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Order placed successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should not stack form fields on desktop screen', async ({ page }) => {
    await page.setViewportSize({ width: 1225, height: 856 });

    // Verify form fields are visible
    const emailField = page.getByLabel('Email Address');
    const cardNumberField = page.getByLabel('Card Number');
    const expiryField = page.getByLabel('Expiry Date');
    const cvvField = page.getByLabel('CVV');
    const billingAddressField = page.getByLabel('Billing Address');
    const submitButton = page.getByRole('button', { name: 'Place Order' });

    await expect(emailField).toBeVisible();
    await expect(cardNumberField).toBeVisible();
    await expect(expiryField).toBeVisible();
    await expect(cvvField).toBeVisible();
    await expect(billingAddressField).toBeVisible();
    await expect(submitButton).toBeVisible();

    // Fill in form fields
    await emailField.fill('desktop@example.com');
    await cardNumberField.fill('4111111111111111');
    await expiryField.fill('12/25');
    await cvvField.fill('123');
    await billingAddressField.fill('123 Main St');

    // Verify form fields are displayed inline (not stacked)
    const formContainer = page.locator('[data-testid="checkout-form-container"]');
    const fieldElements = page.locator('[data-testid="form-field"]');
    const fieldCount = await fieldElements.count();

    expect(fieldCount).toBe(5);

    // Verify fields are displayed inline (check display style)
    const firstField = fieldElements.first();
    const secondField = fieldElements.nth(1);

    const firstDisplay = await firstField.evaluate((el)) => window.getComputedStyle(el).display);
    const secondDisplay = await secondField.evaluate((el)) => window.getComputedStyle(el).display);

    expect(firstDisplay).not.toBe('block');
    expect(secondDisplay).not.toBe('block');

    // Verify fields are displayed inline using flex or grid
    const firstInline = await firstField.evaluate((el)) => window.getComputedStyle(el).display);
    const secondInline = await secondField.evaluate((el)) => window.getComputedStyle(el).display);

    expect(firstInline).toBe('inline-flex');
    expect(secondInline).toBe('inline-flex');

    // Verify submit button is inline-flex
    const buttonInline = await submitButton.evaluate((el)) => window.getComputedStyle(el).display);
    expect(buttonInline).toBe('inline-flex');

    // Verify form is submitted successfully
    await submitButton.click();
    const successMessage = page.getByText('Order placed successfully');
    await expect(successMessage).toBeVisible();
  });
});
